package local.lito381.server;
import java.io.*;import java.util.*;
/** A bounded plan on the existing event scope, released only by its accepted nonterminal HP frame. */
final class NativeAcceptedShockMutation {
 static final String FIELD="nativeAcceptedShockPlan";
 static final class Plan {
  final NativeAreaMaterialAction.Context context;final NativeShockPlayerAction.Scope scope;final BattleSpellCatalog.ShockStunSpell spell;final Protocol.AttackSpellRequest request;final List<ClientSession> audience;final List<Output> outputs=new ArrayList<>();boolean done;long expiry,effect;
  Plan(NativeAreaMaterialAction.Context c,NativeShockPlayerAction.Scope s,BattleSpellCatalog.ShockStunSpell spell,Protocol.AttackSpellRequest request,List<ClientSession> audience){context=c;scope=s;this.spell=spell;this.request=request;this.audience=audience;}
 }
 record Output(ClientSession receiver,NativePlayerCommit.Binding binding,byte[] packet,String note){}
 static Plan get(NativeShockPlayerAction.Scope s){return s==null?null:(Plan)CombatAccess.field(s,FIELD);}
 static boolean plan(ClientSession pc,BattleSpellCatalog.ShockStunSpell spell,Protocol.AttackSpellRequest request,ClientSession target,List<ClientSession> audience){var c=NativeAreaMaterialAction.current.get();var s=NativeShockPlayerAction.scope(c);if(c==null||c.pc!=pc||s==null||s.target.get()!=target||!s.admitted)return false;if(get(s)!=null)throw new IllegalStateException("duplicate accepted Shock Stun plan");CombatAccess.set(s,FIELD,new Plan(c,s,spell,request,audience==null?null:List.copyOf(audience)));return true;}
 static void apply(Plan p,NativePlayerCommit.Frame frame){var c=p.context;var target=p.scope.target.get();if(target==null||!frame.accepted||frame.fatal||frame.after<=0||frame.pc!=target)return;NativeSourcePlayerActionLock.runPairOrdered(c.pc,target,()->{synchronized(c.hub){var timed=(BattleTimedStatus)CombatAccess.field(target,"timedStatus");synchronized(timed){if(p.done||!frame.event.target().matches(target)||!NativeShockPlayerAction.valid(c,p.scope,true)||(int)CombatAccess.field(target,"playerHp")<=0)return;p.done=true;Object oldScope=CombatAccess.field(c,NativeShockPlayerAction.FIELD);int oldStage=(int)CombatAccess.field(c,NativeCompanionNegative.STAGE);CombatAccess.set(c,NativeShockPlayerAction.FIELD,p.scope);CombatAccess.set(c,NativeCompanionNegative.STAGE,5);try{NativeAreaMaterialAction.owned(c,()->{p.effect=c.phase.equals("WORLD")?c.pc.nativeAcceptedShockWorld(p.spell,p.request,target,c.map,c.instance,p.scope.x,p.scope.y):c.pc.nativeAcceptedShockBattle(p.spell,p.request,target,p.scope.x,p.scope.y,p.audience);});p.expiry=(long)CombatAccess.field(timed,"shockStunExpiresAtNanos");}catch(IOException failure){throw new UncheckedIOException(failure);}finally{CombatAccess.set(c,NativeCompanionNegative.STAGE,oldStage);CombatAccess.set(c,NativeShockPlayerAction.FIELD,oldScope);}}}});}
 static void emit(Plan p){var c=p.context;for(var out:p.outputs){Runnable[] completion={null};NativeSourcePlayerActionLock.run(out.receiver,()->{if(out.binding.matches(out.receiver))completion[0]=NativeRolePublication.completion(out.receiver,()->{boolean valid;synchronized(c.hub){var target=p.scope.target.get();valid=target!=null&&out.binding.matches(out.receiver)&&c.player(out.receiver)&&NativeShockPlayerAction.valid(c,p.scope,true)&&(int)CombatAccess.field(target,"playerHp")>0; if(valid){var timed=(BattleTimedStatus)CombatAccess.field(target,"timedStatus");synchronized(timed){valid=timed.shockStunActive(System.nanoTime())&&(long)CombatAccess.field(timed,"shockStunExpiresAtNanos")==p.expiry;}}}if(valid)try{out.receiver.nativeSelfOriginalSend(out.packet,out.note);}catch(IOException failure){throw new UncheckedIOException(failure);}});});if(completion[0]!=null)completion[0].run();}p.outputs.clear();}
 static void completed(NativePlayerCommit.Frame frame){var s=(Object)frame.event.defense()instanceof NativeShockPlayerAction.Linked linked?linked.scope:null;var p=get(s);try{if(p!=null){apply(p,frame);emit(p);}}catch(RuntimeException failure){NativePlayerCommit.secondaryFailure("accepted Shock Stun",failure);}finally{if(s!=null)CombatAccess.set(s,FIELD,null);NativeShockPlayerAction.completed(frame);}}
 static boolean captureOutput(ClientSession receiver,byte[] packet,String note){var c=NativeAreaMaterialAction.current.get();var s=NativeShockPlayerAction.scope(c);var p=get(s);if(c==null||p==null||(int)CombatAccess.field(c,NativeCompanionNegative.STAGE)!=5)return NativeAreaMaterialAction.nativeAcceptedShockOriginalCaptureOutput(receiver,packet,note);var binding=c.bindings.get(receiver);if(binding!=null)p.outputs.add(new Output(receiver,binding,packet.clone(),note));return true;}
 private NativeAcceptedShockMutation(){}
}
